package com.redisplay.client;

/** Selects the Windows pen packet sequence generated by one direct-touch contact. */
final class FingerContactPolicy {
    static final class Actions {
        final int begin;
        final int move;
        final int end;

        Actions(int begin, int move, int end) {
            this.begin = begin;
            this.move = move;
            this.end = end;
        }
    }

    static Actions forMode(boolean mouseMode) {
        // A finger has no hover sensor. While it is touching the tablet it must
        // remain a real contact, including in Host mouse mode, so Windows can
        // hold the left button and drag until the finger is lifted.
        return new Actions(
                NetworkServer.PEN_ACTION_DOWN,
                NetworkServer.PEN_ACTION_MOVE,
                NetworkServer.PEN_ACTION_UP);
    }

    private FingerContactPolicy() {}
}
